  try{
    var j = JSON.parse(String(result));
    var d = j.data;
    if(!d){ return ''; }
    var p = Number(d.page);
    var tp = Number(d.total_pages);
    if(isNaN(p) || isNaN(tp)){ return ''; }
    if(p >= tp){ return ''; }
    return String(baseUrl).replace(/page=[0-9]+/, 'page=' + (p + 1));
  }catch(e){
    return '';
  }
})()}}

